package special

import "math"

// The float64-argument forms of Factorial2 and Perm that the nd package
// applies: an argument that is not an integer (or exceeds int32) gives NaN.
// They are the scalar bodies behind Factorial2To and PermTo (generated by
// tools/geninline); keeping the rule here, in one place, is what makes the
// array kernels equal to the nd functions element for element.

// intArg reports whether x is an integer of magnitude at most MaxInt32.
func intArg(x float64) bool { return x == math.Trunc(x) && math.Abs(x) <= math.MaxInt32 }

// factorial2F is Factorial2 of a float64 integer, NaN otherwise.
func factorial2F(n float64) float64 {
	if !intArg(n) {
		return math.NaN()
	}
	return Factorial2(int(n))
}

// permF is Perm of two float64 integers, NaN if either is not one.
func permF(n, k float64) float64 {
	if !intArg(n) || !intArg(k) {
		return math.NaN()
	}
	return Perm(int64(n), int64(k))
}
